+	listed, err := s.GateBindings(ctx, "aaaa")
+	if err != nil {
+		t.Fatalf("GateBindings: %v", err)
+	}
+	if len(listed) != 2 {
+		t.Fatalf("GateBindings returned %d bindings, want 2: %+v", len(listed), listed)
+	}
