+func TestEveryOutcomeSaysWhatToDoNext(t *testing.T) {
+	t.Parallel()
+	for _, outcome := range machine.Outcomes() {
+		if strings.TrimSpace(outcome.NextAction()) == "" {
+			t.Fatalf("%s carries no next action", outcome)
+		}
