+// all become ask.
+func TestParseActionFailsClosedToAsk(t *testing.T) {
+	for _, in := range []string{
+		"", "   ", "unknown", "fixme", "fix it", "FIX_ME", "auto", "resolve",
+		"none", "null", "note.", "fix-it", "ﬁx",
+	} {
+		if got := findings.ParseAction(in); got != findings.ActionAsk {
